@Transactional
public Reservation createStaffOffer(Integer requestId, Integer vetId, Instant startTime, String staffUsername) {
	SchedulingRequest request = lockCoordinator.lockRequest(requestId);
	if (request == null) {
		throw new IllegalArgumentException("Request not found");
	}

	verifyClaimant(requestId, staffUsername);

	Integer ownerId = request.getOwner().getId();
	Integer petId = request.getPet().getId();

	lockCoordinator.lockResources(List.of(ownerId), List.of(petId), List.of(vetId), List.of(requestId), null, null);

	Vet vet = vetRepository.findById(vetId).orElseThrow(() -> new IllegalArgumentException("Vet not found"));

	int duration = request.getDurationMinutes() != null ? request.getDurationMinutes() : 30;
	Instant endTime = startTime.plus(Duration.ofMinutes(duration));

	boolean feasible = liveFeasibilityService.checkFeasibility(vetId, ownerId, petId, startTime, endTime,
			request.getCareType(), request.getRequiredSpecialty(), request.getOwnerHorizonEnd(), requestId);

	if (!feasible) {
		throw new IllegalStateException("Proposed slot is not feasible (violates calendar, availability, or DST)");
	}

	// Revoke prior active reservations
	List<Reservation> reservations = reservationRepository.findByRequestId(requestId);
	for (Reservation r : reservations) {
		if (r.getStatus() == ReservationStatus.ACTIVE) {
			r.setStatus(ReservationStatus.REVOKED);
			reservationRepository.save(r);
		}
	}

	Instant now = timeService.now();
	Instant expiresAt = now.plus(Duration.ofHours(24));
	if (request.getFallbackDeadline() != null && expiresAt.isAfter(request.getFallbackDeadline())) {
		expiresAt = request.getFallbackDeadline();
	}

	Reservation offer = new Reservation();
	offer.setRequest(request);
	offer.setOwner(request.getOwner());
	offer.setPet(request.getPet());
	offer.setVet(vet);
	offer.setReservationType(ReservationType.STAFF_OFFER);
	offer.setStatus(ReservationStatus.ACTIVE);
	offer.setStartTime(startTime);
	offer.setEndTime(endTime);
	offer.setExpiresAt(expiresAt);
	reservationRepository.save(offer);

	refreshClaimActivity(requestId, staffUsername);

	auditService.recordEvent(AuditEventType.STAFF_OFFER_ISSUED, staffUsername, "STAFF", "RESERVATION",
			String.valueOf(offer.getId()), "OFFER_ISSUED", Map.of("requestId", String.valueOf(requestId), "vetId",
					String.valueOf(vetId), "startTime", startTime.toString(), "expiresAt", expiresAt.toString()));

	notificationService.sendNotification(request.getOwner(), "notification.staffOffer.title",
			"notification.staffOffer.message", startTime.toString(), "/scheduling/requests/" + requestId);

	return offer;
}

package org.springframework.samples.petclinic.scheduling.service;

import java.util.Collection;
import java.util.List;
import java.util.Objects;
import java.util.TreeSet;

import org.springframework.samples.petclinic.owner.Owner;
import org.springframework.samples.petclinic.owner.Pet;
import org.springframework.samples.petclinic.scheduling.model.Appointment;
import org.springframework.samples.petclinic.scheduling.model.Reservation;
import org.springframework.samples.petclinic.scheduling.model.SchedulingRequest;
import org.springframework.samples.petclinic.vet.Vet;
import org.springframework.stereotype.Service;

import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import jakarta.persistence.PersistenceContext;

@Service
public class LockCoordinator {

	@PersistenceContext
	private EntityManager entityManager;

	public LockCoordinator() {
	}

	public LockCoordinator(EntityManager entityManager) {
		this.entityManager = entityManager;
	}

	public LockedResources lockResources(Collection<Integer> ownerIds, Collection<Integer> petIds,
			Collection<Integer> vetIds, Collection<Integer> requestIds, Collection<Integer> appointmentIds,
			Collection<Integer> reservationIds) {

		LockedResources locked = new LockedResources();

		// 1. Owner
		if (ownerIds != null) {
			for (Integer id : sortIds(ownerIds)) {
				locked.addOwner(entityManager.find(Owner.class, id, LockModeType.PESSIMISTIC_WRITE));
			}
		}

		// 2. Pet
		if (petIds != null) {
			for (Integer id : sortIds(petIds)) {
				locked.addPet(entityManager.find(Pet.class, id, LockModeType.PESSIMISTIC_WRITE));
			}
		}

		// 3. Vet
		if (vetIds != null) {
			for (Integer id : sortIds(vetIds)) {
				locked.addVet(entityManager.find(Vet.class, id, LockModeType.PESSIMISTIC_WRITE));
			}
		}

		// 4. SchedulingRequest
		if (requestIds != null) {
			for (Integer id : sortIds(requestIds)) {
				locked.addRequest(entityManager.find(SchedulingRequest.class, id, LockModeType.PESSIMISTIC_WRITE));
			}
		}

		// 5. Appointment
		if (appointmentIds != null) {
			for (Integer id : sortIds(appointmentIds)) {
				locked.addAppointment(entityManager.find(Appointment.class, id, LockModeType.PESSIMISTIC_WRITE));
			}
		}

		// 6. Reservation
		if (reservationIds != null) {
			for (Integer id : sortIds(reservationIds)) {
				locked.addReservation(entityManager.find(Reservation.class, id, LockModeType.PESSIMISTIC_WRITE));
			}
		}

		return locked;
	}

	public Owner lockOwner(Integer ownerId) {
		if (ownerId == null) {
			return null;
		}
		return entityManager.find(Owner.class, ownerId, LockModeType.PESSIMISTIC_WRITE);
	}

	public Pet lockPet(Integer petId) {
		if (petId == null) {
			return null;
		}
		return entityManager.find(Pet.class, petId, LockModeType.PESSIMISTIC_WRITE);
	}

	public Vet lockVet(Integer vetId) {
		if (vetId == null) {
			return null;
		}
		return entityManager.find(Vet.class, vetId, LockModeType.PESSIMISTIC_WRITE);
	}

	public SchedulingRequest lockRequest(Integer requestId) {
		if (requestId == null) {
			return null;
		}
		return entityManager.find(SchedulingRequest.class, requestId, LockModeType.PESSIMISTIC_WRITE);
	}

	public Appointment lockAppointment(Integer appointmentId) {
		if (appointmentId == null) {
			return null;
		}
		return entityManager.find(Appointment.class, appointmentId, LockModeType.PESSIMISTIC_WRITE);
	}

	public Reservation lockReservation(Integer reservationId) {
		if (reservationId == null) {
			return null;
		}
		return entityManager.find(Reservation.class, reservationId, LockModeType.PESSIMISTIC_WRITE);
	}

	private TreeSet<Integer> sortIds(Collection<Integer> ids) {
		TreeSet<Integer> sorted = new TreeSet<>();
		for (Integer id : ids) {
			if (id != null) {
				sorted.add(id);
			}
		}
		return sorted;
	}

@Transactional(propagation = Propagation.REQUIRES_NEW)
public void processOverdueFallback(Integer requestId) {
	SchedulingRequest initial = schedulingRequestRepository.findById(requestId).orElse(null);
	if (initial == null || (initial.getStatus() != RequestStatus.STAFF_QUEUED
			&& initial.getStatus() != RequestStatus.STAFF_OFFERED)) {
		return;
	}

	Instant now = timeService.now();
	if (initial.getFallbackDeadline() == null || initial.getFallbackDeadline().isAfter(now)) {
		return;
	}

	Integer ownerId = initial.getOwner() != null ? initial.getOwner().getId() : null;
	Integer petId = initial.getPet() != null ? initial.getPet().getId() : null;
	Integer vetId = initial.getPreferredVet() != null ? initial.getPreferredVet().getId() : null;

	lockCoordinator.lockResources(ownerId != null ? List.of(ownerId) : null, petId != null ? List.of(petId) : null,
			vetId != null ? List.of(vetId) : null, List.of(requestId), null, null);

	SchedulingRequest locked = schedulingRequestRepository.findById(requestId).orElse(null);
	if (locked == null || (locked.getStatus() != RequestStatus.STAFF_QUEUED
			&& locked.getStatus() != RequestStatus.STAFF_OFFERED)) {
		return;
	}

	if (locked.getFallbackDeadline() == null || locked.getFallbackDeadline().isAfter(now)) {
		return;
	}

	// Expire active reservations
	List<Reservation> reservations = reservationRepository.findByRequestId(requestId);
	for (Reservation r : reservations) {
		if (r.getStatus() == ReservationStatus.ACTIVE) {
			r.setStatus(ReservationStatus.EXPIRED);
			reservationRepository.save(r);
			auditService.recordEvent(AuditEventType.OFFER_EXPIRED, "SYSTEM", "SYSTEM", "RESERVATION",
					String.valueOf(r.getId()), "FALLBACK_DEADLINE_EXPIRED",
					Map.of("requestId", String.valueOf(requestId)));
		}
	}

	// Delete staff claim
	Optional<StaffClaim> claimOpt = staffClaimRepository.findByRequestId(requestId);
	claimOpt.ifPresent(staffClaimRepository::delete);

	locked.setStatus(RequestStatus.EXPIRED);
	if (locked.getRetentionDeadline() == null) {
		ClinicSettings settings = clinicSettingsService.getSettings();
		locked.setRetentionDeadline(now.plus(Duration.ofDays(settings.getSensitiveDataRetentionDays())));
	}
	schedulingRequestRepository.save(locked);

	auditService.recordEvent(AuditEventType.REQUEST_EXPIRED, "SYSTEM", "SYSTEM", "SCHEDULING_REQUEST",
			String.valueOf(requestId), "FALLBACK_DEADLINE_EXPIRED", Map.of("requestId", String.valueOf(requestId)));

	notificationService.sendNotification(locked.getOwner(), "notification.offerExpired.title",
			"notification.offerExpired.message", "", "/scheduling/requests/" + requestId);

	log.info("Expired fallback request ID: {}", requestId);
}
